UIExplosionParticle=function(game,x,y,key,frame){Phaser.Particle.call(this,game,x,y,key,frame);this.fadeSpeed=0.0125-Math.random()*0.0083;this.kill();};UIExplosionParticle.prototype=Object.create(Phaser.Particle.prototype);UIExplosionParticle.prototype.constructor=UIExplosionParticle;UIExplosionParticle.prototype.onEmit=function(){this.body.x+=this.body.velocity.x*(Math.random()*6.0+1.0)/15.0;this.body.y+=this.body.velocity.y*(Math.random()*6.0+1.0)/15.0;};UIExplosionParticle.prototype.update=function(){this.alpha-=this.fadeSpeed;this.scale.x+=0.0083;this.scale.y+=0.0083;};UIExplosionParticle.prototype.retire=function(){this.kill();};